{"command":"cat << 'EOF' > src/options.hpp
#ifndef OPTIONS_HPP
#define OPTIONS_HPP

#include <string>
#include <vector>
#include <optional>
#include <iostream>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <cstdint>
#include <sys/types.h>

enum class CaseSensitivity { Smart, Sensitive, Insensitive };
enum class PatternType { Regex, Glob, Fixed };
enum class ColorWhen { Auto, Always, Never };
enum class HyperlinkWhen { Auto, Always, Never };
enum class StripCwd { Auto, Always, Never };

enum class FileType {
    File, Directory, Symlink, Executable, Empty, Socket, Pipe, CharDev, BlockDev
};

struct SizeFilter {
    enum Mode { Min, Max, Exact } mode;
    uint64_t bytes;
};

struct TimeFilter {
    enum Mode { Newer, Older } mode;
    time_t timestamp;
};

struct OwnerFilter {
    std::optional<uid_t> uid;
    std::optional<gid_t> gid;
    bool negate_uid = false;
    bool negate_gid = false;
};

struct Options {
    std::string pattern = "";
    std::vector<std::string> additional_patterns;
    std::vector<std::string> search_paths;

    bool hidden = false;
    bool no_ignore = false;
    bool no_ignore_vcs = false;
    bool no_require_git = false;
    bool no_ignore_parent = false;

    CaseSensitivity case_sensitivity = CaseSensitivity::Smart;
    PatternType pattern_type = PatternType::Regex;

    bool absolute_path = false;
    bool list_details = false;
    bool follow_symlinks = false;
    bool full_path = false;
    bool print0 = false;

    std::optional<int> max_depth;
    int min_depth = 0;

    std::vector<std::string> excludes;
    bool prune = false;

    std::vector<FileType> file_types;
    std::vector<std::string> extensions;
    std::vector<SizeFilter> size_filters;
    std::vector<TimeFilter> time_filters;
    std::optional<OwnerFilter> owner_filter;

    std::optional<std::string> format;
    std::vector<std::string> exec_cmd;
    std::vector<std::string> exec_batch_cmd;
    size_t batch_size = 0;

    ColorWhen color = ColorWhen::Auto;
    HyperlinkWhen hyperlink = HyperlinkWhen::Never;
    std::vector<std::string> ignore_contain;
    std::vector<std::string> custom_ignore_files;

    int threads = 0; // 0 = default (hardware concurrency)
    std::optional<uint64_t> max_results;
    bool quiet = false;
    bool show_errors = false;

    std::optional<std::string> base_directory;
    std::string path_separator = "/";
    StripCwd strip_cwd_prefix = StripCwd::Auto;
    bool one_file_system = false;
};

#endif
EOF"}

