{"command":"cat << 'EOF' > src/arg_parser.hpp
#ifndef ARG_PARSER_HPP
#define ARG_PARSER_HPP

#include "options.hpp"
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <pwd.h>
#include <grp.h>
#include <time.h>
#include <sys/stat.h>

inline void print_version() {
    std::cout << "fd 10.3.0\n";
}

inline void print_short_help() {
    std::cout << "A program to find entries in your filesystem\n\n"
              << "Usage: executable [OPTIONS] [pattern] [path]...\n\n"
              << "Arguments:\n"
              << "  [pattern]  the search pattern (a regular expression, unless '--glob' is used; optional)\n"
              << "  [path]...  the root directories for the filesystem search (optional)\n\n"
              << "Options:\n"
              << "  -H, --hidden                     Search hidden files and directories\n"
              << "  -I, --no-ignore                  Do not respect .(git|fd)ignore files\n"
              << "  -s, --case-sensitive             Case-sensitive search (default: smart case)\n"
              << "  -i, --ignore-case                Case-insensitive search (default: smart case)\n"
              << "  -g, --glob                       Glob-based search (default: regular expression)\n"
              << "  -a, --absolute-path              Show absolute instead of relative paths\n"
              << "  -l, --list-details               Use a long listing format with file metadata\n"
              << "  -L, --follow                     Follow symbolic links\n"
              << "  -p, --full-path                  Search full abs. path (default: filename only)\n"
              << "  -d, --max-depth <depth>          Set maximum search depth (default: none)\n"
              << "  -E, --exclude <pattern>          Exclude entries that match the given glob pattern\n"
              << "  -t, --type <filetype>            Filter by type: file (f), directory (d/dir), symlink (l),\n"
              << "                                   executable (x), empty (e), socket (s), pipe (p), char-device\n"
              << "                                   (c), block-device (b)\n"
              << "  -e, --extension <ext>            Filter by file extension\n"
              << "  -S, --size <size>                Limit results based on the size of files\n"
              << "      --changed-within <date|dur>  Filter by file modification time (newer than)\n"
              << "      --changed-before <date|dur>  Filter by file modification time (older than)\n"
              << "  -o, --owner <user:group>         Filter by owning user and/or group\n"
              << "      --format <fmt>               Print results according to template\n"
              << "  -x, --exec <cmd>...              Execute a command for each search result\n"
              << "  -X, --exec-batch <cmd>...        Execute a command with all search results at once\n"
              << "  -c, --color <when>               When to use colors [default: auto] [possible values: auto,\n"
              << "                                   always, never]\n"
              << "      --hyperlink[=<when>]         Add hyperlinks to output paths [default: never] [possible\n"
              << "                                   values: auto, always, never]\n"
              << "      --ignore-contain <name>      Ignore directories containing the named entry\n"
              << "  -h, --help                       Print help (see more with '--help')\n"
              << "  -V, --version                    Print version\n";
}

inline void print_long_help() {
    // Print full detailed help string matching executable --help
    extern const char* FULL_HELP_TEXT;
    std::cout << FULL_HELP_TEXT;
}

inline uint64_t parse_size_bytes(const std::string& val_str, SizeFilter::Mode& mode) {
    if (val_str.empty()) throw std::runtime_error("empty size");
    std::string s = val_str;
    if (s[0] == '+') {
        mode = SizeFilter::Min;
        s = s.substr(1);
    } else if (s[0] == '-') {
        mode = SizeFilter::Max;
        s = s.substr(1);
    } else {
        mode = SizeFilter::Exact;
    }

    size_t idx = 0;
    while (idx < s.size() && (std::isdigit(s[idx]) || s[idx] == '.')) {
        idx++;
    }
    if (idx == 0) throw std::runtime_error("invalid size number");

    double num = std::stod(s.substr(0, idx));
    std::string unit = s.substr(idx);
    for (auto& c : unit) c = std::tolower(c);

    uint64_t multiplier = 1;
    if (unit == "" || unit == "b") {
        multiplier = 1;
    } else if (unit == "k" || unit == "ki" || unit == "kib" || unit == "kb") {
        multiplier = 1024ULL;
    } else if (unit == "m" || unit == "mi" || unit == "mib" || unit == "mb") {
        multiplier = 1024ULL * 1024ULL;
    } else if (unit == "g" || unit == "gi" || unit == "gib" || unit == "gb") {
        multiplier = 1024ULL * 1024ULL * 1024ULL;
    } else if (unit == "t" || unit == "ti" || unit == "tib" || unit == "tb") {
        multiplier = 1024ULL * 1024ULL * 1024ULL * 1024ULL;
    } else {
        throw std::runtime_error("invalid size unit");
    }

    return static_cast<uint64_t>(num * multiplier);
}

inline time_t parse_date_dur(const std::string& val_str) {
    time_t now = time(nullptr);
    if (val_str.empty()) return now;

    // Check if relative duration e.g. 10s, 5m, 2h, 1d, 2w, 1y
    size_t idx = 0;
    while (idx < val_str.size() && (std::isdigit(val_str[idx]) || val_str[idx] == '.')) {
        idx++;
    }
    if (idx > 0 && idx < val_str.size()) {
        double num = std::stod(val_str.substr(0, idx));
        std::string unit = val_str.substr(idx);
        for (auto& c : unit) c = std::tolower(c);
        uint64_t secs = 0;
        if (unit == "s" || unit == "sec" || unit == "seconds") secs = static_cast<uint64_t>(num);
        else if (unit == "m" || unit == "min" || unit == "minutes") secs = static_cast<uint64_t>(num * 60);
        else if (unit == "h" || unit == "hr" || unit == "hours") secs = static_cast<uint64_t>(num * 3600);
        else if (unit == "d" || unit == "day" || unit == "days") secs = static_cast<uint64_t>(num * 86400);
        else if (unit == "w" || unit == "week" || unit == "weeks") secs = static_cast<uint64_t>(num * 86400 * 7);
        else if (unit == "y" || unit == "year" || unit == "years") secs = static_cast<uint64_t>(num * 86400 * 365);

        if (secs > 0) {
            return now - secs;
        }
    }

    // Try epoch timestamp @123456
    if (val_str[0] == '@') {
        return static_cast<time_t>(std::stoll(val_str.substr(1)));
    }

    // Try YYYY-MM-DD or YYYY-MM-DD HH:MM:SS
    struct tm tm_time = {};
    if (strptime(val_str.c_str(), "%Y-%m-%d %H:%M:%S", &tm_time) != nullptr ||
        strptime(val_str.c_str(), "%Y-%m-%d", &tm_time) != nullptr) {
        return mktime(&tm_time);
    }

    return now;
}

inline OwnerFilter parse_owner_filter(const std::string& val_str) {
    OwnerFilter filter;
    std::string s = val_str;
    size_t colon = s.find(':');
    std::string u_str = (colon == std::string::npos) ? s : s.substr(0, colon);
    std::string g_str = (colon == std::string::npos) ? "" : s.substr(colon + 1);

    if (!u_str.empty()) {
        if (u_str[0] == '!') {
            filter.negate_uid = true;
            u_str = u_str.substr(1);
        }
        if (!u_str.empty()) {
            if (std::all_of(u_str.begin(), u_str.end(), ::isdigit)) {
                filter.uid = static_cast<uid_t>(std::stoul(u_str));
            } else {
                struct passwd* pw = getpwnam(u_str.c_str());
                if (pw) filter.uid = pw->pw_uid;
            }
        }
    }

    if (!g_str.empty()) {
        if (g_str[0] == '!') {
            filter.negate_gid = true;
            g_str = g_str.substr(1);
        }
        if (!g_str.empty()) {
            if (std::all_of(g_str.begin(), g_str.end(), ::isdigit)) {
                filter.gid = static_cast<gid_t>(std::stoul(g_str));
            } else {
                struct group* gr = getgrnam(g_str.c_str());
                if (gr) filter.gid = gr->gr_gid;
            }
        }
    }

    return filter;
}

#endif
EOF"}

