inline uint64_t parse_size_bytes(const std::string& val_str, SizeFilter::Mode& mode) {
    if (val_str.empty()) throw std::runtime_error("empty size");
    std::string s = val_str;
    if (s[0] == '+') {
        mode = SizeFilter::Min;
        s = s.substr(1);
    } else if (s[0] == '-') {
        mode = SizeFilter::Max;
        s = s.substr(1);
    } else {
        mode = SizeFilter::Exact;
    }

    size_t idx = 0;
    while (idx < s.size() && (std::isdigit(s[idx]) || s[idx] == '.')) {
        idx++;
    }
    if (idx == 0) throw std::runtime_error("invalid size number");

    double num = std::stod(s.substr(0, idx));
    std::string unit = s.substr(idx);
    for (auto& c : unit) c = std::tolower(c);

    uint64_t multiplier = 1;
    if (unit == "" || unit == "b") {
        multiplier = 1;
    } else if (unit == "k" || unit == "ki" || unit == "kib" || unit == "kb") {
        multiplier = 1024ULL;
    } else if (unit == "m" || unit == "mi" || unit == "mib" || unit == "mb") {
        multiplier = 1024ULL * 1024ULL;
    } else if (unit == "g" || unit == "gi" || unit == "gib" || unit == "gb") {
        multiplier = 1024ULL * 1024ULL * 1024ULL;
    } else if (unit == "t" || unit == "ti" || unit == "tib" || unit == "tb") {
        multiplier = 1024ULL * 1024ULL * 1024ULL * 1024ULL;
    } else {
        throw std::runtime_error("invalid size unit");
    }

    return static_cast<uint64_t>(num * multiplier);
