    size_t idx = 0;
    while (idx < val_str.size() && (std::isdigit(val_str[idx]) || val_str[idx] == '.')) {
        idx++;
    }
    if (idx > 0 && idx < val_str.size()) {
        double num = std::stod(val_str.substr(0, idx));
        std::string unit = val_str.substr(idx);
        for (auto& c : unit) c = std::tolower(c);
        uint64_t secs = 0;
        if (unit == "s" || unit == "sec" || unit == "seconds") secs = static_cast<uint64_t>(num);
        else if (unit == "m" || unit == "min" || unit == "minutes") secs = static_cast<uint64_t>(num * 60);
        else if (unit == "h" || unit == "hr" || unit == "hours") secs = static_cast<uint64_t>(num * 3600);
        else if (unit == "d" || unit == "day" || unit == "days") secs = static_cast<uint64_t>(num * 86400);
        else if (unit == "w" || unit == "week" || unit == "weeks") secs = static_cast<uint64_t>(num * 86400 * 7);
        else if (unit == "y" || unit == "year" || unit == "years") secs = static_cast<uint64_t>(num * 86400 * 365);

        if (secs > 0) {
            return now - secs;
        }
    }

