inline std::string expand_placeholders(const std::string& tpl, const std::string& path_str) {
    std::string base = path_str;
    size_t slash = base.rfind('/');
    if (slash != std::string::npos) {
        base = base.substr(slash + 1);
    }
    std::string parent = ".";
    if (slash != std::string::npos) {
        parent = path_str.substr(0, slash);
        if (parent.empty()) parent = "/";
    }
    std::string stem = path_str;
    size_t dot = stem.rfind('.');
    if (dot != std::string::npos && (slash == std::string::npos || dot > slash)) {
        stem = stem.substr(0, dot);
    }
    std::string basestem = base;
    size_t bdot = basestem.rfind('.');
    if (bdot != std::string::npos) {
        basestem = basestem.substr(0, bdot);
    }

    std::string res;
    size_t i = 0;
    while (i < tpl.size()) {
        if (tpl.substr(i, 2) == "{{") {
            res += "{";
            i += 2;
        } else if (tpl.substr(i, 2) == "}}") {
            res += "}";
            i += 2;
        } else if (tpl.substr(i, 2) == "{}") {
            res += path_str;
            i += 2;
        } else if (tpl.substr(i, 3) == "{/}") {
            res += base;
            i += 3;
        } else if (tpl.substr(i, 4) == "{//}") {
            res += parent;
            i += 4;
        } else if (tpl.substr(i, 3) == "{.}") {
            res += stem;
            i += 3;
        } else if (tpl.substr(i, 4) == "{/.}") {
            res += basestem;
            i += 4;
        } else {
            res += tpl[i++];
        }
    }
    return res;
}

class Walker {
public:
    Options opts;
    Matcher matcher;
    uint64_t match_count = 0;
    std::vector<std::string> collected_matches;
    dev_t start_dev = 0;
    std::set<std::pair<dev_t, ino_t>> visited_symlinks;

    Walker(const Options& options) : opts(options), matcher(options) {}

    void execute_cmd(const std::vector<std::string>& cmd_tokens) {
        if (cmd_tokens.empty()) return;
        std::vector<char*> c_args;
        for (const auto& token : cmd_tokens) {
            c_args.push_back(const_cast<char*>(token.c_str()));
        }
        c_args.push_back(nullptr);

        pid_t pid = fork();
        if (pid == 0) {
            execvp(c_args[0], c_args.data());
            perror("execvp failed");
            exit(1);
        } else if (pid > 0) {
            int status;
            waitpid(pid, &status, 0);
        }
    }

    void handle_match(const std::string& formatted_path, const std::string& cmd_path, bool is_dir) {
        match_count++;

        if (opts.quiet) {
            return;
        }

        if (opts.list_details || !opts.exec_batch_cmd.empty()) {
            collected_matches.push_back(cmd_path);
            return;
        }

        if (!opts.exec_cmd.empty()) {
            std::vector<std::string> final_cmd;
            bool has_ph = false;
            for (const auto& token : opts.exec_cmd) {
