                    token.find("{/}") != std::string::npos ||
                    token.find("{//}") != std::string::npos ||
                    token.find("{.}") != std::string::npos ||
                    token.find("{/.}") != std::string::npos) {
                    has_ph = true;
                }
                final_cmd.push_back(expand_placeholders(token, cmd_path));
            }
            if (!has_ph) {
                final_cmd.push_back(cmd_path);
