            } else {
                opts.exec_batch_cmd.push_back(arg);
            }
            continue;
        }

        if (stop_opts) {
            pos_args.push_back(arg);
            continue;
        }

        if (arg == "--") {
            stop_opts = true;
            continue;
        }

        if (arg == "-h") {
            print_short_help();
            exit(0);
