        } else if (arg == "-F" || arg == "--fixed-strings") {
            opts.pattern_type = PatternType::Fixed;
        } else if (arg == "-a" || arg == "--absolute-path") {
            opts.absolute_path = true;
        } else if (arg == "--relative-path") {
            opts.absolute_path = false;
        } else if (arg == "-l" || arg == "--list-details") {
            opts.list_details = true;
        } else if (arg == "-L" || arg == "--follow") {
            opts.follow_symlinks = true;
        } else if (arg == "--no-follow") {
            opts.follow_symlinks = false;
        } else if (arg == "-p" || arg == "--full-path") {
            opts.full_path = true;
        } else if (arg == "-0" || arg == "--print0") {
            opts.print0 = true;
        } else if (arg == "-1") {
            opts.max_results = 1;
        } else if (arg == "-q" || arg == "--quiet" || arg == "--has-results") {
            opts.quiet = true;
