            if (!val.empty()) opts.excludes.push_back(val);
        } else if (arg.rfind("-t", 0) == 0 || arg.rfind("--type", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (arg.size() > 2 && arg[1] == 't' ? arg.substr(2) : (i + 1 < argc ? argv[++i] : ""));
            if (val == "f" || val == "file") opts.file_types.push_back(FileType::File);
            else if (val == "d" || val == "dir" || val == "directory") opts.file_types.push_back(FileType::Directory);
            else if (val == "l" || val == "symlink") opts.file_types.push_back(FileType::Symlink);
            else if (val == "x" || val == "executable") opts.file_types.push_back(FileType::Executable);
            else if (val == "e" || val == "empty") opts.file_types.push_back(FileType::Empty);
            else if (val == "s" || val == "socket") opts.file_types.push_back(FileType::Socket);
            else if (val == "p" || val == "pipe") opts.file_types.push_back(FileType::Pipe);
            else if (val == "c" || val == "char") opts.file_types.push_back(FileType::CharDev);
            else if (val == "b" || val == "block") opts.file_types.push_back(FileType::BlockDev);
        } else if (arg.rfind("-e", 0) == 0 || arg.rfind("--extension", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (arg.size() > 2 && arg[1] == 'e' ? arg.substr(2) : (i + 1 < argc ? argv[++i] : ""));
