                TimeFilter tf;
                tf.mode = TimeFilter::Older;
                tf.timestamp = parse_date_dur(val);
                opts.time_filters.push_back(tf);
            }
        } else if (arg.rfind("-o", 0) == 0 || arg.rfind("--owner", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (arg.size() > 2 && arg[1] == 'o' ? arg.substr(2) : (i + 1 < argc ? argv[++i] : ""));
            if (!val.empty()) {
                opts.owner_filter = parse_owner_filter(val);
            }
        } else if (arg.rfind("--format", 0) == 0) {
