        } else if (arg.rfind("-C", 0) == 0 || arg.rfind("--base-directory", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (arg.size() > 2 && arg[1] == 'C' ? arg.substr(2) : (i + 1 < argc ? argv[++i] : ""));
            opts.base_directory = val;
        } else if (arg.rfind("--search-path", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (i + 1 < argc ? argv[++i] : "");
            if (!val.empty()) opts.search_paths.push_back(val);
        } else if (arg.rfind("--ignore-file", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (i + 1 < argc ? argv[++i] : "");
            if (!val.empty()) opts.custom_ignore_files.push_back(val);
        } else if (arg.rfind("--ignore-contain", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (i + 1 < argc ? argv[++i] : "");
            if (!val.empty()) opts.ignore_contain.push_back(val);
        } else if (arg.rfind("-c", 0) == 0 || arg.rfind("--color", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (arg.size() > 2 && arg[1] == 'c' ? arg.substr(2) : (i + 1 < argc ? argv[++i] : ""));
            if (val == "always") opts.color = ColorWhen::Always;
            else if (val == "never") opts.color = ColorWhen::Never;
            else opts.color = ColorWhen::Auto;
        } else if (arg.rfind("--strip-cwd-prefix", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : "";
            if (val == "never") opts.strip_cwd_prefix = StripCwd::Never;
            else if (val == "always" || val.empty()) opts.strip_cwd_prefix = StripCwd::Always;
            else opts.strip_cwd_prefix = StripCwd::Auto;
        } else if (arg.rfind("-j", 0) == 0 || arg.rfind("--threads", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (arg.size() > 2 && arg[1] == 'j' ? arg.substr(2) : (i + 1 < argc ? argv[++i] : ""));
