        } else if (arg.rfind("--max-results", 0) == 0) {
            std::string val = (arg.find('=') != std::string::npos) ? arg.substr(arg.find('=') + 1) : (i + 1 < argc ? argv[++i] : "");
            if (!val.empty()) opts.max_results = std::stoull(val);
        } else if (arg[0] == '-') {
            // Cluster of short flags e.g. -HIp0
            for (size_t k = 1; k < arg.size(); ++k) {
                char ch = arg[k];
                if (ch == 'H') opts.hidden = true;
                else if (ch == 'I') opts.no_ignore = true;
                else if (ch == 's') opts.case_sensitivity = CaseSensitivity::Sensitive;
                else if (ch == 'i') opts.case_sensitivity = CaseSensitivity::Insensitive;
                else if (ch == 'g') opts.pattern_type = PatternType::Glob;
                else if (ch == 'F') opts.pattern_type = PatternType::Fixed;
                else if (ch == 'a') opts.absolute_path = true;
                else if (ch == 'l') opts.list_details = true;
                else if (ch == 'L') opts.follow_symlinks = true;
                else if (ch == 'p') opts.full_path = true;
                else if (ch == '0') opts.print0 = true;
                else if (ch == '1') opts.max_results = 1;
                else if (ch == 'q') opts.quiet = true;
                else if (ch == 'u') { opts.hidden = true; opts.no_ignore = true; }
                else {
                    std::cerr << "error: unexpected argument '" << arg << "' found\n\n  tip: to pass '" << arg << "' as a value, use '-- " << arg << "'\n\nUsage: executable [OPTIONS] [pattern] [path]...\n\nFor more information, try '--help'.\n";
                    exit(2);
                }
            }
        } else {
            pos_args.push_back(arg);
        }
    }

    if (!pos_args.empty()) {
        if (opts.search_paths.empty()) {
            opts.pattern = pos_args[0];
            for (size_t k = 1; k < pos_args.size(); ++k) {
                opts.search_paths.push_back(pos_args[k]);
            }
        } else {
            opts.pattern = pos_args[0];
        }
    }

    return true;
}

int main(int argc, char** argv) {
    Options opts;
    parse_args(argc, argv, opts);

    // Check path-separator error
    if (!opts.full_path && opts.pattern_type != PatternType::Glob &&
        (opts.pattern.find('/') != std::string::npos || opts.pattern.find('\\') != std::string::npos)) {
        std::cerr << "[fd error]: The search pattern '" << opts.pattern
                  << "' contains a path-separation character ('/') and will not lead to any search results.\n\n"
                  << "If you want to search for all files inside the '" << opts.pattern
                  << "' directory, use a match-all pattern:\n\n"
                  << "  fd . '" << opts.pattern << "'\n\n"
                  << "Instead, if you want your pattern to match the full file path, use:\n\n"
                  << "  fd --full-path '" << opts.pattern << "'\n";
        return 1;
    }

    Walker walker(opts);
    return walker.run();
}
EOF"}

